-- Colorscheme generated by matugen from the wallpaper (see matugen/config.toml)
-- pcall: on a fresh machine colors/matugen.lua does not exist until matugen has run once
local ok, err = pcall(vim.cmd.colorscheme, 'matugen')
if not ok then
  vim.notify('Colorscheme matugen not loaded: ' .. err, vim.log.levels.WARN)
end
